const { DistributionAPI } = require('helios-core/common')

const ConfigManager = require('./configmanager')

// Served from the BCRutility distribution repo (generated by Nebula).
// Must match BASE_URL in Nebula's .env -- if you change one, change both and
// re-run `generate distro`, since artifact URLs are baked into the index.
exports.REMOTE_DISTRO_URL = 'https://raw.githubusercontent.com/Vesuviuz1/BCRutility/main/distribution.json'

const api = new DistributionAPI(
    ConfigManager.getLauncherDirectory(),
    null, // Injected forcefully by the preloader.
    null, // Injected forcefully by the preloader.
    exports.REMOTE_DISTRO_URL,
    false
)

exports.DistroAPI = api